/* ---------- marks: 64 polar samples from the top, so any two morph point-to-point ---------- */
const R = 17;
const polar = (f: (t: number) => number): Pts =>
  Array.from({ length: 64 }, (_, i) => {
    const t = -Math.PI / 2 + (i / 64) * Math.PI * 2,
