  polar((t) => {
    const ux = Math.cos(t),
      uy = Math.sin(t);
    let r = 0;
    ring.forEach(([ax, ay], i) => {
      const [bx, by] = ring[(i + 1) % ring.length],
        ex = bx - ax,
        ey = by - ay,
        det = ex * uy - ux * ey;
      if (Math.abs(det) < 1e-9) return;
      const d = (ex * ay - ax * ey) / det,
        s = (ux * ay - uy * ax) / det;
      if (d > 0 && s >= -1e-9 && s <= 1 + 1e-9) r = Math.max(r, d);
