  opacity: 1;
  transition: none;
}

/* ---------- bursts: one card per actor's burst of updates ---------- */
/* A card is its rows: each paints its own slice of the card, the edges round it off. */
.v-activity-feed[data-variant="bursts"] .v-activity-feed__entry {
  --v-activity-gap: 0px;
}
.v-activity-feed[data-variant="bursts"] .v-activity-feed__entry[data-last] {
  --v-activity-gap: var(--s-3);
}
.v-activity-feed[data-variant="bursts"]
  .v-activity-feed__entry[data-last][data-day-end] {
  --v-activity-gap: calc(var(--s-3) + var(--s-4));
}
.v-activity-feed[data-variant="bursts"] .v-activity-feed__entry::before {
  content: "";
  position: absolute;
  inset: 0 0 var(--v-activity-gap);
  background: var(--v-canvas);
  border: 1px solid var(--v-border);
  border-block-width: 0;
}
.v-activity-feed[data-variant="bursts"] .v-activity-feed__entry[data-first]::before {
  border-block-start-width: 1px;
  border-start-start-radius: var(--r-card-sm);
  border-start-end-radius: var(--r-card-sm);
}
.v-activity-feed[data-variant="bursts"] .v-activity-feed__entry[data-last]::before {
  border-block-end-width: 1px;
  border-end-end-radius: var(--r-card-sm);
  border-end-start-radius: var(--r-sm);
}
/* The gap to the next card, kept inside the last row's height. */
.v-activity-feed[data-variant="bursts"] .v-activity-feed__entry[data-last]::after {
  content: "";
  display: block;
  block-size: var(--v-activity-gap);
}
.v-activity-feed__card {
  position: relative;
  padding-inline: var(--s-4);
}
.v-activity-feed__entry[data-first] > .v-activity-feed__card {
  padding-block-start: var(--s-3);
}
.v-activity-feed__entry[data-last] > .v-activity-feed__card {
  padding-block-end: var(--s-3);
}
.v-activity-feed__card-head {
  position: relative;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  align-items: center;
  column-gap: var(--s-3);
  min-height: 28px;
  list-style: none;
  border-radius: var(--r-sm);
}
.v-activity-feed__card-head::-webkit-details-marker {
  display: none;
}
summary.v-activity-feed__card-head {
  cursor: pointer;
}
summary.v-activity-feed__card-head:focus-visible {
  outline: 2px solid var(--v-blue);
  outline-offset: 2px;
}
.v-activity-feed__card-who {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0 var(--s-2);
  min-width: 0;
}
.v-activity-feed__card-name {
  font-weight: var(--fw-semibold);
  overflow-wrap: anywhere;
}
.v-activity-feed__card-count {
  font-size: var(--fs-meta);
  color: var(--v-text-2);
  font-variant-numeric: tabular-nums;
}
.v-activity-feed__chevron {
  inline-size: 16px;
  block-size: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  color: var(--v-text-2);
  transition: rotate var(--t-element) var(--enter);
}
.v-activity-feed__fold[open]:not([data-closing]) .v-activity-feed__chevron {
  rotate: 180deg;
}
.v-activity-feed[data-variant="bursts"] .v-activity-feed__inner {
  margin-inline-start: calc(28px + var(--s-3));
  padding-block: var(--s-2);
}
.v-activity-feed[data-variant="bursts"]
  .v-activity-feed__entry[data-first]
  .v-activity-feed__inner {
  padding-block-start: calc(var(--s-1) + var(--s-2));
}
.v-activity-feed[data-variant="bursts"]
  .v-activity-feed__entry[data-last]
  .v-activity-feed__inner {
  padding-block-end: 0;
}
.v-activity-feed[data-variant="bursts"]
  .v-activity-feed__entry:not([data-first])
  .v-activity-feed__inner {
  box-shadow: inset 0 1px 0 var(--v-border);
}

/* Quiet and reduced motion: instant, nothing loops. */
.v-activity-feed[data-motion-quiet] *,
.v-activity-feed[data-motion-quiet] *::before {
  animation: none;
  transition: none;
}
@media (prefers-reduced-motion: reduce) {
  .v-activity-feed *,
  .v-activity-feed *::before {
    animation: none;
    transition: none;
  }
}
@media (max-width: 480px) {
  .v-activity-feed[data-variant="thread"] .v-activity-feed__inner {
    column-gap: var(--s-3);
  }
  .v-activity-feed[data-variant="thread"] .v-activity-feed__group-text {
    padding-inline-start: calc(36px + var(--s-3));
  }
  .v-activity-feed__footer {
    justify-content: flex-start;
    gap: var(--s-3) var(--s-5);
  }
}
@media (max-width: 600px) {
  .v-activity-feed[data-slot] {
    padding: var(--s-5);
  }
}
@media (max-width: 560px) {
  .v-activity-feed__card {
    padding-inline: var(--s-3);
  }
}
.v-activity-example {
  width: 100%;
  min-width: 0;
  display: grid;
  gap: var(--s-6);
}

}
